const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const namibia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Namibia'))
    .geometry();

  const startDate = '2021-01-01';
  const endDate = '2021-02-01';

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(namibia);

  const imageCount = chirps.size().getInfo();
  console.log(`CHIRPS Images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log('No data for January 2021.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Sum all daily precipitation
  const totalPrecip = chirps.select('precipitation').sum();

  // 4. Calculation - Get mean precipitation across Namibia
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: namibia,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const count = pixelCount.precipitation;
  const meanPrecip = stats.precipitation;

  console.log(`Valid pixels: ${count}`);

  if (count === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Validation & Final Answer
  if (meanPrecip === null || meanPrecip === undefined || isNaN(meanPrecip)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  const thresholdMM = 177.8; // 7 inches in mm
  console.log(`Mean total rainfall in Namibia (Jan 2021): ${meanPrecip.toFixed(2)} mm`);
  console.log(`Threshold (7 inches): ${thresholdMM} mm`);

  if (meanPrecip >= thresholdMM) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
